using System.Drawing;
using System.Windows.Forms; //watashi wa watashi sore dake
namespace ZenForms.Core { [ToolboxBitmap(typeof(TabControl))][System.ComponentModel.Category("ZenForms Modern Controls")] public class ZenTabControl:TabControl { public ZenTabControl(){DrawMode=TabDrawMode.OwnerDrawFixed;SizeMode=TabSizeMode.Fixed;ItemSize=new Size(128,36);Padding=new Point(16,6);Font=new Font("Segoe UI Semibold",9f);BackColor=ZenTheme.Background;ForeColor=ZenTheme.Foreground;} protected override void OnDrawItem(DrawItemEventArgs e){if(e.Index<0)return;TabPage page=TabPages[e.Index];Rectangle r=e.Bounds;bool selected=(e.State&DrawItemState.Selected)==DrawItemState.Selected;using(SolidBrush b=new SolidBrush(selected?ZenTheme.Surface:ZenTheme.Background))e.Graphics.FillRectangle(b,r);if(selected){using(SolidBrush b=new SolidBrush(ZenTheme.Primary))e.Graphics.FillRectangle(b,r.X+12,r.Bottom-3,r.Width-24,3);}TextRenderer.DrawText(e.Graphics,page.Text,Font,r,selected?ZenTheme.Foreground:ZenTheme.Muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);} } }